-- Additive beta update. Keep journey IDs/history/revisions as the canonical
-- personal data so existing accounts and older clients remain compatible.
alter table public.profiles add column faith_tradition text check (faith_tradition in ('Christian','Jewish','Muslim','Hindu','Buddhist','Sikh','Spiritual, from many traditions','Prefer not to say'));
alter table public.intentions add column for_whom text not null default '' check(char_length(for_whom)<=120);
alter table public.intentions add column for_me boolean not null default false;
alter table public.intentions add column mission_id text;
alter table public.intentions add column mission_step integer check(mission_step between 1 and 5);
-- Existing beneficiaries are retained, without inventing a choice of "For me".
-- Do not update reflected intentions: historical person remains the fallback.
create table public.priority_words (name text primary key, priority_group text not null, position integer not null);
create table public.quick_pick_cards (id text primary key, title text not null, description text not null, domain text not null, position integer not null, active boolean not null default true);
create table public.missions (
 id text primary key, user_id uuid references auth.users(id) on delete cascade,
 mission_text text not null check(char_length(mission_text) between 1 and 500),
 first_step text not null check(char_length(first_step) between 1 and 500),
 area text not null check(area in ('Be','People','Causes','Passions','Grow')),
 tags text[] not null default '{}',quick_picks text[] not null default '{}',priorities text[] not null default '{}',who_for text[] not null default '{}',
 ladder_step integer not null check(ladder_step between 1 and 5),stage text not null,
 size text not null check(size in ('5-minute','Normal','Stretch')),minutes integer not null check(minutes between 1 and 180),
 cost text not null check(cost in ('Free','$','$$')),setting text not null default '',safety_note text not null default '',provenance text not null default '',
 updated_at timestamptz not null default now()
);
create index missions_owner_step on public.missions(user_id,ladder_step);
create index missions_tags on public.missions using gin(tags);
create table public.night_thoughts (
 id integer primary key,format text not null check(format in ('quote','story','reframe')),text text not null,
 person text not null default '',source text not null default '',credit text not null default '',
 priorities text[] not null default '{}',traditions text[] not null default '{}',once_only boolean not null default false,
 status text not null check(status in ('verified','needs_check')),verification_note text not null default '',checked_against text not null default '',source_urls text[] not null default '{}'
);
create table public.night_thought_history (
 user_id uuid not null references auth.users(id) on delete cascade, day date not null,
 thought_id integer references public.night_thoughts(id),once_only boolean not null default false,
 snapshot jsonb not null,shown_at timestamptz not null default now(),primary key(user_id,day)
);
create index night_thought_history_lookup on public.night_thought_history(user_id,thought_id,shown_at desc);
create table public.support_state (user_id uuid primary key references auth.users(id) on delete cascade,session_id text not null,level integer not null default 0 check(level between 0 and 3));
create table public.quick_pick_responses (user_id uuid not null references auth.users(id) on delete cascade,quick_pick_id text not null references public.quick_pick_cards(id),session_id text not null,choice text not null check(choice in ('love','like','open','pass')),not_now_count integer not null default 0 check(not_now_count>=0),last_shown_at timestamptz not null default now(),primary key(user_id,quick_pick_id));

alter table public.priority_words enable row level security;
alter table public.quick_pick_cards enable row level security;
alter table public.missions enable row level security;
alter table public.night_thoughts enable row level security;
alter table public.night_thought_history enable row level security;
alter table public.support_state enable row level security;
alter table public.quick_pick_responses enable row level security;
revoke all on public.priority_words,public.quick_pick_cards,public.missions,public.night_thoughts,public.night_thought_history,public.support_state,public.quick_pick_responses from public,anon,authenticated;
grant select on public.priority_words,public.quick_pick_cards,public.missions,public.night_thoughts,public.night_thought_history,public.support_state to authenticated;
grant select,insert,update,delete on public.quick_pick_responses to authenticated;
grant all on public.priority_words,public.quick_pick_cards,public.missions,public.night_thoughts,public.night_thought_history,public.support_state,public.quick_pick_responses to service_role;
create policy priority_catalogue on public.priority_words for select to authenticated using(true);
create policy quick_pick_catalogue on public.quick_pick_cards for select to authenticated using(active);
create policy mission_reader on public.missions for select to authenticated using(user_id is null or (select auth.uid())=user_id);
create policy thought_reader on public.night_thoughts for select to authenticated using(status='verified');
create policy thought_history_owner on public.night_thought_history for select to authenticated using((select auth.uid())=user_id);
create policy support_owner on public.support_state for select to authenticated using((select auth.uid())=user_id);
create policy quick_pick_owner on public.quick_pick_responses for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);

-- Read-only normalized views avoid a second writable copy of users' discoveries.
create view public.priorities with (security_invoker=true) as
 select id,user_id,entry->>'title' name,entry->'meta'->>'priority_group' priority_group,
 case when entry->>'state' in ('let_go','released') then 'let_go'
 when entry->>'state' in ('mine','important') or kind='strength' then 'important' else 'working_on' end state,
 entry->>'source' source,revision
 from public.journey_entries where kind in ('value','strength');
create view public.user_interests with (security_invoker=true) as
 select e.id,e.user_id,e.entry->>'title' interest,
 case when e.entry->>'state' in ('craft','all_in') then 'All in' when e.entry->>'state' in ('love','into_it') then 'Into it' when e.entry->>'state' in ('tried','want_to_try') then 'Want to try' else 'Maybe' end stage,
 least(5,greatest(1,coalesce((select max(i.mission_step)+1 from public.intentions i join public.check_ins c on c.intention_id=i.id and c.user_id=i.user_id where i.interest_id=e.id and i.user_id=e.user_id and c.outcome='yes' and i.mission_id is not null),1))) current_ladder_step,
 e.entry->>'state' in ('ember','paused','on_pause') paused,
 (select max(i.day) from public.intentions i join public.check_ins c on c.intention_id=i.id and c.user_id=i.user_id where i.interest_id=e.id and i.user_id=e.user_id and c.outcome='yes') last_activity_date
 from public.journey_entries e where e.kind='interest';
revoke all on public.priorities,public.user_interests from public,anon,authenticated;
grant select on public.priorities,public.user_interests to authenticated,service_role;

-- Client-supplied mission links must refer to a visible row and its actual step.
create function public.validate_mission_link() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if new.mission_id is not null and not exists(select 1 from public.missions m where m.id=new.mission_id and m.ladder_step=new.mission_step and (m.user_id is null or m.user_id=new.user_id)) then
  raise exception 'Choose a current mission from your own library.' using errcode='23514';
 end if;
 if new.for_me and new.for_whom<>'' then raise exception 'Choose one beneficiary.' using errcode='23514'; end if;
 return new;
end;
$$;
create trigger validate_mission_link before insert or update on public.intentions for each row execute function public.validate_mission_link();
revoke execute on function public.validate_mission_link() from public,anon,authenticated;

